// ZITERA CYBER_LAB — Hardened Offline Curriculum Vault (Encrypted Enclave)
// Proprietary course curriculum, mission briefings, and technical guides.
// Encrypted and deflated at rest; deobfuscated in-memory for active sessions only.

import { strFromU8, inflateSync } from 'fflate'
import type { LabContent } from './engineClient'

export interface MissionBriefing {
  labId: string
  targetAppName: string
  targetAppSubtitle: string
  whyItMatters: string
  targetArchitecture: string
  missionObjectives: string
}

const VAULT_KEY = 'Z1t3rA_CuRr1cUlUm_Pr0t3ct10n_V4uLt_2026!'
const ENCRYPTED_VAULT_PAYLOAD = ''

interface DecodedOfflineVault {
  briefings: Record<string, MissionBriefing>
  labData: Record<string, LabContent>
}

let cachedVault: DecodedOfflineVault | null = null

function getVault(): DecodedOfflineVault {
  if (!cachedVault) {
    try {
      const binStr = atob(ENCRYPTED_VAULT_PAYLOAD)
      const len = binStr.length
      const u8 = new Uint8Array(len)
      for (let i = 0; i < len; i++) {
        u8[i] = binStr.charCodeAt(i) ^ VAULT_KEY.charCodeAt(i % VAULT_KEY.length)
      }
      const decompressed = inflateSync(u8)
      const jsonStr = strFromU8(decompressed)
      cachedVault = JSON.parse(jsonStr) as DecodedOfflineVault
    } catch (err) {
      console.error('[SECURITY ENCLAVE] Failed to unpack curriculum vault:', err)
      cachedVault = { briefings: {}, labData: {} }
    }
  }
  return cachedVault
}

export const OFFLINE_MISSION_BRIEFINGS: Record<string, MissionBriefing> = new Proxy({} as Record<string, MissionBriefing>, {
  get(_, prop: string) {
    return getVault().briefings[prop]
  },
  has(_, prop: string) {
    return prop in getVault().briefings
  },
  ownKeys() {
    return Object.keys(getVault().briefings)
  },
  getOwnPropertyDescriptor(_, prop: string) {
    return Object.getOwnPropertyDescriptor(getVault().briefings, prop)
  }
})

export const OFFLINE_LAB_DATA: Record<string, LabContent> = new Proxy({} as Record<string, LabContent>, {
  get(_, prop: string) {
    return getVault().labData[prop]
  },
  has(_, prop: string) {
    return prop in getVault().labData
  },
  ownKeys() {
    return Object.keys(getVault().labData)
  },
  getOwnPropertyDescriptor(_, prop: string) {
    return Object.getOwnPropertyDescriptor(getVault().labData, prop)
  }
})

export function getOfflineLabContent(labId: string): LabContent {
  const key = labId.toUpperCase()
  const vault = getVault().labData
  if (vault[key]) {
    return vault[key]
  }
  return vault['A01'] || {
    id: key,
    title: `Lab ${key}`,
    readme: `# Lab ${key}\n\nMemuat konten praktikum...`,
    hints: [],
  }
}

export function getMissionBriefing(labId: string): MissionBriefing {
  const key = labId.toUpperCase()
  const vault = getVault().briefings
  if (vault[key]) {
    return vault[key]
  }
  return {
    labId,
    targetAppName: 'Target Sandbox Portal',
    targetAppSubtitle: 'Corporate Security Assessment Target',
    whyItMatters: 'Pelajari kerentanan keamanan web kritis sesuai standar OWASP Top 10:2025 untuk melindungi aset digital perusahaan dari kebocoran data.',
    targetArchitecture: 'Arsitektur web microservices dengan REST API backend dan basis data relasional.',
    missionObjectives: '1. Petakan alur request pada endpoint target.\n2. Uji kelemahan logika otorisasi dan validasi input.\n3. Dapatkan bukti eksploitasi dan ambil flag ZITERA{...}.'
  }
}
